                    rivalChoices: [],
                    profitHistory: [],
                    rivalProfitHistory: [],
                    cmaFined: false
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    priceChoice: '',
                    cartelMessage: false
                };
            }
            this._setupChoiceButtons();
            this._updateBriefing(state);
            this._bindLangRepaint();
        }

        // 1.2.0: text the adapter writes outside the translation table (prices with a decimal comma, the chosen
        // option, the chart text alternative) is repainted after a language switch.
        _bindLangRepaint() {
            if (this._langBound) return;
            this._langBound = true;
            var self = this;
            var again = function() { setTimeout(function() { self._repaint(); }, 0); };
            document.addEventListener('express:langchanged', again);
            try { if (window.mySimulation && window.mySimulation.eventBus && window.mySimulation.eventBus.on) window.mySimulation.eventBus.on('language:changed', again); } catch (e) {}
        }

        _price(choice) {
            var es = this._lang() === 'es';
            if (choice === 'hold') return es ? '\u00a31,50' : '\u00a31.50';
            if (choice === 'undercut') return es ? '\u00a31,40' : '\u00a31.40';
            return '?';
        }

        _repaint() {
            this._syncChoice();
            var canvas = document.getElementById('profitChart');
            if (canvas) canvas.setAttribute('aria-label', this._tx('chart_aria'));
            var st = window.mySimulation && window.mySimulation.state;
            var h = st && st.history && st.history.length ? st.history[st.history.length - 1].results : null;
            if (h) {
                var pt = document.getElementById('playerPriceTag');
                if (pt) pt.textContent = this._price(h.playerChoice);
                var rt = document.getElementById('rivalPriceTag');
                if (rt) rt.textContent = this._price(h.aiChoice);
            }
        }

        _setupChoiceButtons() {
            // 1.2.0: the price is a radio group (name priceChoice) styled as two buttons, so it is keyboard
            // operable, announced as one decision, and visible to the platform tests. The hidden input is kept
            // in sync for code that reads it.
            var self = this;
            var radios = document.querySelectorAll('input[name="priceChoice"]');
            for (var i = 0; i < radios.length; i++) {
                if (radios[i].__petrolBound) continue;
                radios[i].__petrolBound = true;
                radios[i].addEventListener('change', function() { self._syncChoice(); });
            }
            this._syncChoice();
        }

        _checkedPrice() {
            var r = document.querySelector('input[name="priceChoice"]:checked');
            return r ? r.value : '';
        }

        _syncChoice() {
            var v = this._checkedPrice();
            var choiceInput = document.getElementById('priceChoiceInput');
            if (choiceInput) choiceInput.value = v;
            var holdBtn = document.getElementById('holdBtn');
            var undercutBtn = document.getElementById('undercutBtn');
            if (holdBtn) holdBtn.classList.toggle('petrol-sim-selected', v === 'hold');
            if (undercutBtn) undercutBtn.classList.toggle('petrol-sim-selected', v === 'undercut');
            var selectedDisplay = document.getElementById('selectedChoiceDisplay');
            var selectedText = document.getElementById('selectedChoiceText');
            if (selectedDisplay) selectedDisplay.style.display = v ? 'block' : 'none';
            if (selectedText) selectedText.textContent = v ? this._tx(v === 'hold' ? 'choice_hold' : 'choice_undercut') : '';
        }

        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUND_BRIEFINGS.length - 1);
            var briefEl = document.getElementById('briefingText');
            var briefKey = 'briefing_r' + (idx + 1);
            var briefTf = (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t.bind(window.mySimulation) : function(k) { return k; };
            if (briefEl) briefEl.innerHTML = briefTf(briefKey);

            var cartelOption = document.getElementById('cartelOption');
            if (cartelOption) cartelOption.style.display = ((state.currentPeriod || 1) === 5) ? 'block' : 'none';

            var isRound6 = (state.currentPeriod || 1) >= 6;
            var cellHH = document.getElementById('cell_hh');
            var cellHU = document.getElementById('cell_hu');
            var cellUH = document.getElementById('cell_uh');
            var cellUU = document.getElementById('cell_uu');
            if (cellHH) cellHH.textContent = isRound6 ? '\u00a3300 / \u00a3300' : '\u00a3500 / \u00a3500';
            if (cellHU) cellHU.textContent = isRound6 ? '\u00a30 / \u00a3450' : '\u00a30 / \u00a3750';
            if (cellUH) cellUH.textContent = isRound6 ? '\u00a3450 / \u00a30' : '\u00a3750 / \u00a30';
            if (cellUU) cellUU.textContent = isRound6 ? '\u00a3100 / \u00a3100' : '\u00a3200 / \u00a3200';

            var vfIndicator = document.getElementById('valueFuelIndicator');
            if (vfIndicator) vfIndicator.style.display = isRound6 ? 'block' : 'none';

            var radios = document.querySelectorAll('input[name="priceChoice"]');
            for (var ri = 0; ri < radios.length; ri++) radios[ri].checked = false;
            this._syncChoice();
            var cartelCheck = document.getElementById('cartelMessage');
            if (cartelCheck) cartelCheck.checked = false;

            var cells = document.querySelectorAll('.petrol-sim-matrix-table td');
            cells.forEach(function(c) { c.classList.remove('petrol-sim-cell-active'); });

            var cmaAlarm = document.getElementById('cmaAlarm');
            if (cmaAlarm) cmaAlarm.style.display = 'none';
            var chartEl = document.getElementById('profitChart');
            if (chartEl) chartEl.setAttribute('aria-label', briefTf('chart_aria'));
        }

        validateDecisions(decisions) {
            // Do NOT call _updateBriefing() here. It resets priceChoiceInput.value to ''
            // (and clears the button selection), so calling it *before* reading the choice
            // below wiped the player selection and made every submit fail the
            // 'choice_warning' guard -> the game was unsubmittable. The panel for the next
            // round is refreshed by initialize() and by the deferred advance in
            // calculateResults(), so this call was both redundant and destructive.
            var choiceInput = document.getElementById('priceChoiceInput');
            var checkedPrice = this._checkedPrice();
            if (checkedPrice) decisions.priceChoice = checkedPrice;
            else if (choiceInput) decisions.priceChoice = choiceInput.value;

            var cartelCheck = document.getElementById('cartelMessage');
            if (cartelCheck) decisions.cartelMessage = cartelCheck.checked;

            if (!decisions.priceChoice || (decisions.priceChoice !== 'hold' && decisions.priceChoice !== 'undercut')) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('choice_warning'), 'warning'
                );
                return false;
            }
            return true;
        }

        _getAiChoice(state) {
            var round = state.currentPeriod;
            var ds = state.domainState;
            var d = state.decisions;
            if (round === 1) return 'hold';
            if (round === 2) return 'undercut';
            if (round === 5 && d.cartelMessage) return 'hold';
            if (ds.playerChoices.length > 0) {
                return ds.playerChoices[ds.playerChoices.length - 1];
            }
            return 'hold';
        }

        _getAiSpeech(round, aiChoice, state) {
            if (round === 1) return window.mySimulation.t('ai_speech_r1');
            if (round === 2) return window.mySimulation.t('ai_speech_r2');
            if (round === 5 && state.decisions.cartelMessage) return window.mySimulation.t('ai_speech_cartel');
            if (round === 6) return window.mySimulation.t('ai_speech_r6');
            var prevChoice = state.domainState.playerChoices.length > 0 ? state.domainState.playerChoices[state.domainState.playerChoices.length - 1] : 'hold';
            if (prevChoice === 'hold') return window.mySimulation.t('ai_speech_tft_coop');
            return window.mySimulation.t('ai_speech_tft_defect');
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var round = state.currentPeriod;

            var aiChoice = this._getAiChoice(state);
            var aiSpeech = this._getAiSpeech(round, aiChoice, state);
            var isRound6 = (round === 6);

            var playerProfit = 0;
            var rivalProfit = 0;

            if (d.priceChoice === 'hold' && aiChoice === 'hold') {
                playerProfit = isRound6 ? 300 : 500;
                rivalProfit = isRound6 ? 300 : 500;
            } else if (d.priceChoice === 'hold' && aiChoice === 'undercut') {
                playerProfit = 0;
                rivalProfit = isRound6 ? 450 : 750;
            } else if (d.priceChoice === 'undercut' && aiChoice === 'hold') {
                playerProfit = isRound6 ? 450 : 750;
                rivalProfit = 0;
            } else {
                playerProfit = isRound6 ? 100 : 200;
                rivalProfit = isRound6 ? 100 : 200;
            }

            var cmaFine = 0;
            if (round === 5 && d.cartelMessage) {
                var caught = Math.random() < 0.4;
                if (caught) {
                    cmaFine = 1500;
                    playerProfit = playerProfit - cmaFine;
                    ds.cmaFined = true;
                }
            }

            ds.cash += playerProfit;
            ds.rivalCash += rivalProfit;
            ds.playerChoices.push(d.priceChoice);
            ds.rivalChoices.push(aiChoice);
            ds.profitHistory.push(playerProfit);
            ds.rivalProfitHistory.push(rivalProfit);

            // 1.2.0 platform score (EQIL 2026-10-30): the share of the range between the worst and the best legal run
            // possible against this rival so far, from _scoreFor(); a run that sent the price-fixing message is graded at half
            if (d.cartelMessage && round === 5) ds.cartelSent = true;
            var overallScoreX = this._scoreFor(ds.profitHistory, ds.cartelSent);
            ds.overallScore = overallScoreX;
            state.domainState.performance = Object.assign({}, state.domainState.performance || {}, { overallScore: overallScoreX });

            var pChoice = d.priceChoice;
            var self = this;
            setTimeout(function() {
                var playerTag = document.getElementById('playerPriceTag');
                if (playerTag) playerTag.textContent = self._price(pChoice);
                var rivalTag = document.getElementById('rivalPriceTag');
                if (rivalTag) rivalTag.textContent = self._price(aiChoice);

                var speechEl = document.getElementById('rivalSpeech');
                if (speechEl) speechEl.textContent = aiSpeech;

                var cells = document.querySelectorAll('.petrol-sim-matrix-table td');
                cells.forEach(function(c) { c.classList.remove('petrol-sim-cell-active'); });
                var cellId = 'cell_' + (pChoice === 'hold' ? 'h' : 'u') + (aiChoice === 'hold' ? 'h' : 'u');
                var activeCell = document.getElementById(cellId);
                if (activeCell) activeCell.classList.add('petrol-sim-cell-active');

                if (cmaFine > 0) {
                    var cmaAlarm = document.getElementById('cmaAlarm');
                    if (cmaAlarm) cmaAlarm.style.display = 'block';
                }
            }, 300);

            // FIX off-by-one: use the pre-increment round captured above (round = N), not
            // state.currentPeriod, which the framework increments to N+1 the instant this
            // function returns -> the old code advanced the briefing to N+2 (after Round 1
            // it showed the Round 3 briefing/payoff-matrix and, entering Round 5, hid the
            // cartel option). round + 1 = N+1 is the correct next round. Kept deferred 1500ms
            // to preserve the result reveal before the next briefing loads; skipped after the
            // final round.
            if (round < this.ROUND_BRIEFINGS.length) {
                setTimeout(function() {
                    self._updateBriefing({ currentPeriod: round + 1, domainState: ds, decisions: d });
                }, 1500);
            }

            return {
                period: round,
                playerChoice: d.priceChoice,
                aiChoice: aiChoice,
                playerProfit: playerProfit,
                rivalProfit: rivalProfit,
                cmaFine: cmaFine,
                cash: ds.cash,
                rivalCash: ds.rivalCash,
                overallScore: overallScoreX,
                score: overallScoreX
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            var self = this;
            uiManager.bind('cashDisplay', 'domainState.cash', function(v) { return self._money(v); });
            uiManager.bind('rivalCashDisplay', 'domainState.rivalCash', function(v) { return self._money(v); });
            uiManager.bind('roundProfitDisplay', 'results.playerProfit', function(v) {
                if (v === undefined || v === null) return '-';
                return self._money(v);
            });
        }

        getChartConfig() {
            var chartTf = (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t.bind(window.mySimulation) : function(k) { return k; };
            return {
                profitChart: {
                    type: 'bar',
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: chartTf('chart_your_profit'),
                                data: [],
                                backgroundColor: 'rgba(0,255,136,0.7)',
                                borderColor: '#00ff88',
                                borderWidth: 1
                            },
                            {
                                label: chartTf('chart_rival_profit'),
                                data: [],
                                backgroundColor: 'rgba(255,71,87,0.7)',
                                borderColor: '#ff4757',
                                borderWidth: 1
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: chartTf('chart_title'), color: '#a0aec0' },
                            legend: { labels: { color: '#a0aec0' } }
                        },
                        scales: {
                            y: { beginAtZero: true, ticks: { color: '#a0aec0' }, grid: { color: 'rgba(255,255,255,0.05)' } },
                            x: { ticks: { color: '#a0aec0' }, grid: { color: 'rgba(255,255,255,0.05)' } }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            var labels = state.domainState.profitHistory.map(function(_, i) { return 'R' + (i + 1); });
            return {
                profitChart: {
                    labels: labels,
                    datasets: [
                        { data: state.domainState.profitHistory },
                        { data: state.domainState.rivalProfitHistory }
                    ]
                }
            };
        }

        // ---- 1.2.0 scoring and debrief (EQIL 2026-10-30) -------------------------------------------------
        // Payoff for one week. Rounds 1-5: case Exhibit 1. Round 6: the ValueFuel matrix.
        _payoff(round, mine, theirs) {
            var six = round === 6;
            if (mine === 'hold' && theirs === 'hold') return six ? 300 : 500;
            if (mine === 'hold') return 0;
            if (theirs === 'hold') return six ? 450 : 750;
            return six ? 100 : 200;
        }

        // Caldorra rule, the same as _getAiChoice: holds in R1, cuts in R2, then copies the previous week; the message holds R5.
        _rivalMove(round, prevMine, message) {
            if (round === 1) return 'hold';
            if (round === 2) return 'undercut';
            if (round === 5 && message) return 'hold';
            return prevMine || 'hold';
        }

        // Profit of a price sequence against the rule, without a fine.
        _runProfit(seq, message) {
            var tot = 0;
            for (var r = 1; r <= seq.length; r++) tot += this._payoff(r, seq[r - 1], this._rivalMove(r, seq[r - 2], message));
            return tot;
        }

        // Best and worst cumulative profit any legal run (no message) could have reached after k weeks.
        _legalRange(k) {
            this._rangeCache = this._rangeCache || {};
            if (this._rangeCache[k]) return this._rangeCache[k];
            var best = -Infinity, worst = Infinity;
            for (var m = 0; m < (1 << k); m++) {
                var seq = [];
                for (var b = 0; b < k; b++) seq.push((m >> b) & 1 ? 'undercut' : 'hold');
                var v = this._runProfit(seq, false);
                if (v > best) best = v;
                if (v < worst) worst = v;
            }
            this._rangeCache[k] = { best: best, worst: worst };
            return this._rangeCache[k];
        }

        // Score 0-100: where the run profit sits between the worst and the best legal run of the same length
        // (six weeks: £1,300 and £2,700). Halved when the price-fixing message was sent (TN §10: never reward it).
        _scoreFor(profits, cartelSent) {
            var k = profits.length;
            if (!k) return 0;
            var cum = profits.reduce(function(s, p) { return s + p; }, 0);
            var rg = this._legalRange(k);
            var outcome = Math.max(0, Math.min(100, Math.round(100 * (cum - rg.worst) / (rg.best - rg.worst))));
            return cartelSent ? Math.round(outcome / 2) : outcome;
        }

        _tierFor(score) {
            if (score >= 90) return 'excellent';
            if (score >= 70) return 'good';
            if (score >= 50) return 'fair';
            return 'needs_improvement';
        }

        _tx(key, vars) {
            var f = (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t.bind(window.mySimulation) : function(k) { return k; };
            var out = String(f(key));
            if (vars) Object.keys(vars).forEach(function(n) { out = out.split('{' + n + '}').join(String(vars[n])); });
            return out;
        }

        _lang() {
            try { if (window.vcI18n && window.vcI18n._lang) return window.vcI18n._lang; } catch (e) {}
            var h = (document.documentElement && document.documentElement.lang) || 'en';
            return String(h).slice(0, 2);
        }

        _money(v) {
            var n = Math.round(Number(v) || 0);
            var sep = this._lang() === 'es' ? '.' : ',';
            var body = String(Math.abs(n)).replace(/\B(?=(\d{3})+(?!\d))/g, sep);
            return (n < 0 ? '-£' : '£') + body;
        }

        getPerformanceSummary(history) {
            if (!history || !history.length) return {};
            var self = this;
            var res = history.map(function(h) { return h.results || {}; });
            var mine = res.map(function(r) { return r.playerChoice; });
            var theirs = res.map(function(r) { return r.aiChoice; });
            var profits = res.map(function(r) { return r.playerProfit || 0; });
            var rivalProfits = res.map(function(r) { return r.rivalProfit || 0; });
            var totalProfit = profits.reduce(function(s, p) { return s + p; }, 0);
            var rivalTotal = rivalProfits.reduce(function(s, p) { return s + p; }, 0);
            var fine = res.reduce(function(s, r) { return s + (r.cmaFine || 0); }, 0);
            var last = history[history.length - 1] || {};
            var lastDs = last.domainState || (window.mySimulation && window.mySimulation.state && window.mySimulation.state.domainState) || {};
            var cartelSent = !!lastDs.cartelSent;
            var h5 = history[4];
            if (h5 && h5.decisions && h5.decisions.cartelMessage) cartelSent = true;
            var score = this._scoreFor(profits, cartelSent);
            var outcome = this._scoreFor(profits, false);
            var tier = this._tierFor(score);
            var stars = tier === 'excellent' ? 3 : tier === 'good' ? 2 : tier === 'fair' ? 1 : 0;
            var n = mine.length, full = n >= 6;
            var bothHeld = 0;
            for (var i = 0; i < n; i++) if (mine[i] === 'hold' && theirs[i] === 'hold') bothHeld++;

            var insights = [];
            if (cartelSent) insights.push(this._tx(fine > 0 ? 'ins_cartel_caught' : 'ins_cartel_clean'));
            var allCut = full && mine.every(function(c) { return c === 'undercut'; });
            var allHold = full && mine.every(function(c) { return c === 'hold'; });
            var copied = 0, mismatched = 0, mutualCuts = 0;
            for (var r = 2; r <= n; r++) { if (mine[r - 1] === theirs[r - 2]) copied++; }
            for (var q = 3; q <= n; q++) {
                if (mine[q - 1] !== theirs[q - 1]) mismatched++;
                if (mine[q - 1] === 'undercut' && theirs[q - 1] === 'undercut') mutualCuts++;
            }
            if (allCut) insights.push(this._tx('ins_allcut'));
            else if (allHold) insights.push(this._tx(rivalTotal > totalProfit ? 'ins_allhold_gap' : 'ins_allhold', { gap: this._money(rivalTotal - totalProfit) }));
            else if (full && copied >= 4 && mismatched >= 3) insights.push(this._tx('ins_echo', { n: mismatched }));
            else if (full && mutualCuts >= 3) insights.push(this._tx('ins_war', { n: mutualCuts }));
            insights.push(this._tx('ins_scripted'));
            if (!allCut && !allHold) {
                if (mine[0] === 'undercut') insights.push(this._tx('ins_r1_cut'));
                else insights.push(this._tx('ins_r1_hold'));
            }
            if (full && !cartelSent && mine[1] === 'hold' && mine[2] === 'hold' && mine[3] === 'hold' && mine[4] === 'hold') insights.push(this._tx('ins_held_mid'));
            if (full && !cartelSent && !allCut && mine[3] === 'hold' && mine[4] === 'undercut' && theirs[5] === 'undercut') insights.push(this._tx('ins_r5_unravel'));
            if (full && !allCut && !allHold) {
                if (mine[5] === 'undercut' && theirs[5] === 'hold') insights.push(this._tx('ins_r6_cut'));
                else if (mine[5] === 'hold' && theirs[5] === 'hold') insights.push(this._tx('ins_r6_hold'));
            }
            insights = insights.slice(0, 5);

            // Turning point: the week whose change (alone) would have added the most to the run, or the message.
            var turning = '';
            if (full) {
                if (cartelSent) turning = this._tx('tp_message');
                else {
                    var base = this._runProfit(mine, false), bestGain = 0, bestRound = 0;
                    for (var k = 1; k <= 6; k++) {
                        var alt = mine.slice(); alt[k - 1] = alt[k - 1] === 'hold' ? 'undercut' : 'hold';
                        var g = this._runProfit(alt, false) - base;
                        if (g > bestGain) { bestGain = g; bestRound = k; }
                    }
                    if (!bestRound) turning = this._tx('tp_none');
                    else {
                        var chose = mine[bestRound - 1];
                        var why = chose === 'undercut' ? 'tp_why_copied' : (bestRound === 1 ? 'tp_why_fixed' : (bestRound === 6 ? 'tp_why_last' : 'tp_why_cut'));
                        turning = this._tx('tp_round', {
                            r: bestRound,
                            chose: this._tx(chose === 'hold' ? 'choice_hold' : 'choice_undercut'),
                            alt: this._tx(chose === 'hold' ? 'choice_undercut' : 'choice_hold'),
                            gain: this._money(bestGain)
                        }) + ' ' + this._tx(why);
                    }
                }
            }

            var questions = [this._tx('dq_1'), this._tx('dq_2'), this._tx('dq_3')];
            return {
                totalProfit: totalProfit,
                rivalProfit: rivalTotal,
                cmaFine: fine,
                weeksBothHeld: bothHeld,
                stars: stars,
                performance: tier,
                performanceKey: tier,
                performanceLabel: this._tx('perf_' + tier),
                outcomeScore: outcome,
                processScore: cartelSent ? 0 : 100,
                composite: score,
                overallScore: score,
                totalScore: score,
                score: score,
                turningPoint: turning,
                discussionQuestions: questions,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            if (!summary || typeof summary.overallScore !== 'number') {
                summary = (window.mySimulation && window.mySimulation.state) ? this.getPerformanceSummary(window.mySimulation.state.history) : summary;
            }
            if (!summary || typeof summary.overallScore !== 'number') return '';
            var self = this;
            var esc = function(v) { return String(v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); };
            var html = '<div class="petrol-sim-debrief">';
            html += '<h3>' + esc(this._tx('debrief_heading')) + '</h3>';
            html += '<p class="petrol-sim-debrief-score"><strong>' + summary.overallScore + '/100</strong> &middot; ' + esc(summary.performanceLabel) + '</p>';
            html += '<p class="petrol-sim-debrief-sub">' + esc(this._tx('debrief_outcome', { v: summary.outcomeScore })) + ' &middot; ' + esc(this._tx('debrief_process', { v: summary.processScore })) + '</p>';
            html += '<ul class="petrol-sim-debrief-kpis">';
            html += '<li><span>' + esc(this._tx('your_profit')) + '</span> <b>' + this._money(summary.totalProfit) + '</b></li>';
            html += '<li><span>' + esc(this._tx('rival_profit')) + '</span> <b>' + this._money(summary.rivalProfit) + '</b></li>';
            html += '<li><span>' + esc(this._tx('debrief_both_held')) + '</span> <b>' + summary.weeksBothHeld + '</b></li>';
            html += '<li><span>' + esc(this._tx('col_cma_fine')) + '</span> <b>' + (summary.cmaFine > 0 ? this._money(summary.cmaFine) : '-') + '</b></li>';
            html += '</ul>';
            if (summary.turningPoint) html += '<h4>' + esc(this._tx('debrief_turning')) + '</h4><p>' + esc(summary.turningPoint) + '</p>';
            html += '<h4>' + esc(this._tx('debrief_insights')) + '</h4><ul class="petrol-sim-debrief-insights">';
            (summary.insights || []).forEach(function(t) { html += '<li>' + esc(t) + '</li>'; });
            html += '</ul><h4>' + esc(this._tx('debrief_questions')) + '</h4><ol class="petrol-sim-debrief-questions">';
            (summary.discussionQuestions || []).forEach(function(t) { html += '<li>' + esc(t) + '</li>'; });
            html += '</ol><p class="petrol-sim-debrief-note">' + esc(this._tx('debrief_scale')) + '</p></div>';
            return html;
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.cmaFine > 0) return window.mySimulation.t('hint_cma');
            if (results.playerProfit <= 0) return window.mySimulation.t('hint_loss');
            if (results.playerChoice === 'hold' && results.aiChoice === 'hold') return window.mySimulation.t('hint_coop');
            if (results.playerChoice === 'undercut' && results.aiChoice === 'undercut') return window.mySimulation.t('hint_war');
            if (results.playerProfit === 750 || results.playerProfit === 450) return window.mySimulation.t('hint_defect_win');
            return null;
        }

        getHistoryTableConfig() {
            var self = this;
            var choice = function(v) { return v === 'hold' || v === 'undercut' ? self._tx(v === 'hold' ? 'choice_hold' : 'choice_undercut') : (v || '-'); };
            return [
                { key: 'results.playerChoice', label: 'Your Choice', i18nKey: 'col_your_choice', formatter: choice },
                { key: 'results.aiChoice', label: 'Rival Choice', i18nKey: 'col_rival_choice', formatter: choice },
                { key: 'results.playerProfit', label: 'Your Profit', i18nKey: 'col_your_profit', formatter: function(v) { return self._money(v); } },
                { key: 'results.rivalProfit', label: 'Rival Profit', i18nKey: 'col_rival_profit', formatter: function(v) { return self._money(v); } },
                { key: 'results.cmaFine', label: 'CMA Fine', i18nKey: 'col_cma_fine', formatter: function(v) { return v > 0 ? self._money(v) : '-'; } }
            ];
        }

